{% block title %}{{ title }}{% endblock %}

{% block body %}
<div class=\"form-container\">
    <h2>{{ title }}</h2>

    {{ form_start(form, { 'attr': {'enctype': 'multipart/form-data'} }) }}
    
    <div class=\"form-grid\">
        <div>
            {{ form_label(form.Name) }}
            {{ form_widget(form.Name) }}
        </div>

        <div>
            {{ form_label(form.Type) }}
            {{ form_widget(form.Type) }}
        </div>

        <div>
            {{ form_label(form.Regime) }}
            {{ form_widget(form.Regime) }}
        </div>

        <div>
            {{ form_label(form.Capital) }}
            {{ form_widget(form.Capital) }}
        </div>

        <div class=\"full-width\">
            {{ form_label(form.Couleur) }}
            {{ form_widget(form.Couleur) }}
        </div>

        <div class=\"full-width\">
            {{ form_label(form.Description) }}
            {{ form_widget(form.Description) }}
        </div>
    </div>

    {{ form_rest(form) }}

    <div style=\"display: flex; justify-content: space-between; margin-top: 1rem;\">
        <a href=\"{{ path('app_factions', { worldId: worldId }) }}\" class=\"btn btn-secondary\">← Cancel</a>
        <button type=\"submit\">Save</button>
    </div>
    
    {{ form_end(form) }}
</div>
{% endblock %}
